cd /task && python3 - <<'PY'
import flowio, glob, os, hashlib
files=sorted(glob.glob('input/fcs/*.fcs'))
meta={}
for f in files:
    fd=flowio.FlowData(f, ignore_offset_error=True)
    m=fd.text or {}
    par_raw=m.get('par','')
    try: par=int(str(par_raw).split()[0])
    except: par=fd.channel_count
    chans=[m.get(f'p{i}n', f'p{i}n?') for i in range(1,par+1)]
    volts=[m.get(f'p{i}v','') for i in range(1,par+1)]
    spill=m.get('spillover','')
    meta[os.path.basename(f)]={'events':fd.event_count,'channel_count':fd.channel_count,'par':par,'channels':chans,'voltages':volts,'spill_hash':hashlib.md5(spill.encode()).hexdigest(),'spill':spill,'keys':sorted(m.keys())}
print('PER FILE')
for k,v in meta.items():
    print('\n',k,'events',v['events'],'channel_count',v['channel_count'],'par',v['par'])
    print(' channels:',v['channels'])
    print(' volts:',list(zip(v['channels'],v['voltages'])))
    print(' spill:',v['spill'][:200] + ('...' if len(v['spill'])>200 else ''))
print('\nUNIQUE SPILL MATRICES')
seen={}
for k,v in meta.items(): seen.setdefault(v['spill_hash'],[]).append(k)
for h,fs in seen.items():
    print('HASH',h,'FILES',fs)
    print(meta[fs[0]]['spill'])
print('\nEVENTS')
for k,v in meta.items(): print(k,v['events'])
